import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
import 'package:intl/intl.dart';

void main() { WidgetsFlutterBinding.ensureInitialized(); runApp(const FarisApp()); }

class FarisApp extends StatelessWidget {
  const FarisApp({super.key});
  @override Widget build(BuildContext context) => MaterialApp(
    debugShowCheckedModeBanner: false,
    title: 'برنامج حسابات فارس الأعور',
    theme: ThemeData(useMaterial3: true, colorScheme: ColorScheme.fromSeed(seedColor: const Color(0xFF183B66)), scaffoldBackgroundColor: const Color(0xFFF5F7FB), appBarTheme: const AppBarTheme(backgroundColor: Color(0xFF142944), foregroundColor: Colors.white)),
    home: const Directionality(textDirection: TextDirection.rtl, child: LedgerHome()),
  );
}

class LedgerHome extends StatefulWidget { const LedgerHome({super.key}); @override State<LedgerHome> createState() => _LedgerHomeState(); }
class _LedgerHomeState extends State<LedgerHome> {
  List<Map<String,dynamic>> clients=[]; List<Map<String,dynamic>> entries=[];
  final money=NumberFormat('#,##0.00');
  @override void initState(){super.initState(); _load();}
  Future<void> _load() async { final p=await SharedPreferences.getInstance(); try {setState(() {clients=(jsonDecode(p.getString('clients')??'[]') as List).map((x)=>Map<String,dynamic>.from(x)).toList();entries=(jsonDecode(p.getString('entries')??'[]') as List).map((x)=>Map<String,dynamic>.from(x)).toList();});}catch(_){}}
  Future<void> _save() async {final p=await SharedPreferences.getInstance();await p.setString('clients',jsonEncode(clients));await p.setString('entries',jsonEncode(entries));}
  double balance(String id)=>entries.where((e)=>e['clientId']==id).fold(0.0,(sum,e)=>sum+(e['kind']=='له' ? (e['amount'] as num).toDouble():-(e['amount'] as num).toDouble()));
  Future<void> _addClient() async {final name=TextEditingController();final phone=TextEditingController(); final ok=await showDialog<bool>(context:context,builder:(ctx)=>Directionality(textDirection:TextDirection.rtl,child:AlertDialog(title:const Text('إضافة حساب'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:name,decoration:const InputDecoration(labelText:'اسم العميل / الحساب')),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'رقم الهاتف (اختياري)'))]),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('حفظ'))])));if(ok==true&&name.text.trim().isNotEmpty){setState(()=>clients.add({'id':DateTime.now().microsecondsSinceEpoch.toString(),'name':name.text.trim(),'phone':phone.text.trim()}));await _save();}}
  Future<void> _addEntry({String? selected}) async {if(clients.isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('أضف حساباً أولاً')));return;}String client=selected??clients.first['id'] as String;String kind='له';final amount=TextEditingController();final note=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(ctx)=>StatefulBuilder(builder:(ctx,update)=>Directionality(textDirection:TextDirection.rtl,child:AlertDialog(title:const Text('إضافة حركة مالية'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField<String>(value:client,isExpanded:true,decoration:const InputDecoration(labelText:'الحساب'),items:clients.map((c)=>DropdownMenuItem<String>(value:c['id'] as String,child:Text(c['name'] as String))).toList(),onChanged:(v)=>update(()=>client=v!)),DropdownButtonFormField<String>(value:kind,decoration:const InputDecoration(labelText:'نوع الحركة'),items:['له','عليه'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>update(()=>kind=v!)),TextField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'المبلغ')),TextField(controller:note,decoration:const InputDecoration(labelText:'البيان'))])),actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('حفظ'))]))));final value=double.tryParse(amount.text.trim().replaceAll(',',''));if(ok==true&&value!=null&&value>0){setState(()=>entries.add({'id':DateTime.now().microsecondsSinceEpoch.toString(),'clientId':client,'kind':kind,'amount':value,'note':note.text.trim(),'date':DateTime.now().toIso8601String()}));await _save();}}
  void _details(Map<String,dynamic> c){Navigator.push(context,MaterialPageRoute(builder:(ctx)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:Text(c['name'] as String)),body:StatefulBuilder(builder:(ctx,update){final items=entries.where((e)=>e['clientId']==c['id']).toList().reversed.toList();return Column(children:[Card(margin:const EdgeInsets.all(16),child:ListTile(title:const Text('الرصيد الحالي'),subtitle:Text('${money.format(balance(c['id'] as String))} ر.ي',style:const TextStyle(fontSize:23,fontWeight:FontWeight.bold))),),Expanded(child:items.isEmpty?const Center(child:Text('لا توجد حركات بعد')):ListView.builder(itemCount:items.length,itemBuilder:(ctx,i){final e=items[i];return Card(child:ListTile(title:Text('${e['kind']} — ${money.format(e['amount'])} ر.ي'),subtitle:Text('${e['note']}\n${DateFormat('yyyy/MM/dd HH:mm').format(DateTime.parse(e['date'] as String))}'),isThreeLine:true,trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()async{setState(()=>entries.removeWhere((x)=>x['id']==e['id']));await _save();update((){});})));})),Padding(padding:const EdgeInsets.all(16),child:FilledButton.icon(onPressed:()async{await _addEntry(selected:c['id'] as String);update((){});},icon:const Icon(Icons.add),label:const Text('إضافة حركة')))]);}))));}
  @override Widget build(BuildContext context){final total=clients.fold(0.0,(double s,c)=>s+balance(c['id'] as String));return Scaffold(appBar:AppBar(title:const Text('برنامج حسابات فارس الأعور')),floatingActionButton:FloatingActionButton.extended(onPressed:()=>_addEntry(),icon:const Icon(Icons.add),label:const Text('حركة جديدة')),body:Column(children:[Container(width:double.infinity,margin:const EdgeInsets.all(16),padding:const EdgeInsets.all(22),decoration:BoxDecoration(color:const Color(0xFF142944),borderRadius:BorderRadius.circular(22)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('إجمالي الأرصدة',style:TextStyle(color:Colors.white70)),const SizedBox(height:8),Text('${money.format(total)} ر.ي',style:const TextStyle(fontSize:27,fontWeight:FontWeight.bold,color:Color(0xFFE7BB70)))])),Padding(padding:const EdgeInsets.symmetric(horizontal:16),child:Row(children:[const Expanded(child:Text('الحسابات',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold))),FilledButton.icon(onPressed:_addClient,icon:const Icon(Icons.person_add_alt_1),label:const Text('إضافة حساب'))])),Expanded(child:clients.isEmpty?const Center(child:Text('ابدأ بإضافة أول حساب')):ListView.builder(itemCount:clients.length,itemBuilder:(ctx,i){final c=clients[i];return Card(margin:const EdgeInsets.symmetric(horizontal:16,vertical:5),child:ListTile(leading:const CircleAvatar(child:Icon(Icons.person_outline)),title:Text(c['name'] as String),subtitle:Text('${money.format(balance(c['id'] as String))} ر.ي'),trailing:const Icon(Icons.chevron_left),onTap:()=>_details(c)));}))]));}
}
